for _state, _label in {'idle': 'portrait', 'waving': 'waving', 'jumping': 'jumping',
                        'running': 'working', 'waiting': 'waiting', 'review': 'review', 'failed': 'failed'}.items():
    _SECTIONS['reaction_' + _state] = _SECTIONS[_label]
for _key, _values in _SECTIONS.items():
    for _language, _value in zip(('en', 'ru', 'es', 'de', 'fr', 'zh', 'pt', 'it', 'ar', 'tr', 'hi', 'id'), _values):
        ASSISTANT_TEXT[_language][_key] = _value


def assistant_text(language, key):
    return ASSISTANT_TEXT.get(language, ASSISTANT_TEXT['en']).get(key, ASSISTANT_TEXT['en'].get(key, key))


def companion_display_name(language, mascot, appearance='animated'):
    """Name the visible artwork without changing its stored character identity."""
    return assistant_text(language, 'custom_name' if appearance == 'custom' else mascot)


def assistant_action_text(language, action):
    """One localized title/description pair for menus and their preferences."""
    label = assistant_text(language, action)
    return label if isinstance(label, tuple) else (label, assistant_text(language, action + '_hint'))
